// Tiny deterministic textile normal map, shared by the live material and GLB.
// PNG encoding uses standard CompressionStream: no CDN, native module or Canvas.
export function weavePixels(size=64){const data=new Uint8Array(size*size*4);for(let y=0;y<size;y++)for(let x=0;x<size;x++)data.set([128+(x%4<2?12:-12),128+(y%4<2?12:-12),250,255],(y*size+x)*4);return data;}
function concat(parts){const bytes=new Uint8Array(parts.reduce((n,p)=>n+p.length,0));let at=0;for(const p of parts){bytes.set(p,at);at+=p.length;}return bytes;}
export function crc32(bytes){let crc=0xffffffff;for(const b of bytes){crc^=b;for(let j=0;j<8;j++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^0xffffffff)>>>0;}
const uint=n=>{const b=new Uint8Array(4);new DataView(b.buffer).setUint32(0,n);return b;};
function chunk(type,data){const label=new TextEncoder().encode(type),body=concat([label,data]);return concat([uint(data.length),body,uint(crc32(body))]);}
export async function weavePNG(size=64){const pixels=weavePixels(size),raw=new Uint8Array(size*(size*4+1));for(let y=0;y<size;y++)raw.set(pixels.subarray(y*size*4,(y+1)*size*4),y*(size*4+1)+1);const stream=new Blob([raw]).stream().pipeThrough(new CompressionStream('deflate'));const compressed=new Uint8Array(await new Response(stream).arrayBuffer()),ihdr=concat([uint(size),uint(size),new Uint8Array([8,6,0,0,0])]);return concat([new Uint8Array([137,80,78,71,13,10,26,10]),chunk('IHDR',ihdr),chunk('IDAT',compressed),chunk('IEND',new Uint8Array())]);}
export async function embedWeaveMap(bytes){const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),jsonLength=view.getUint32(12,true),gltf=JSON.parse(new TextDecoder().decode(bytes.subarray(20,20+jsonLength))),binAt=20+jsonLength+8,bin=bytes.subarray(binAt),image=await weavePNG(),imageAt=bin.length,padded=Math.ceil(image.length/4)*4;
 const bufferView=gltf.bufferViews.length;gltf.bufferViews.push({buffer:0,byteOffset:imageAt,byteLength:image.length});gltf.images=[{name:'DAWG woven textile normal',bufferView,mimeType:'image/png'}];gltf.samplers=[{magFilter:9729,minFilter:9987,wrapS:10497,wrapT:10497}];gltf.textures=[{sampler:0,source:0}];
 for(const m of gltf.materials)if(/Outfit|Footwear|Accent/.test(m.name)&&m.pbrMetallicRoughness.metallicFactor<.5)m.normalTexture={index:0,scale:.16,extensions:{KHR_texture_transform:{scale:[5,5]}}};
 gltf.extensionsUsed=[...new Set([...(gltf.extensionsUsed||[]),'KHR_texture_transform'])];gltf.buffers[0].byteLength=bin.length+padded;const json=new TextEncoder().encode(JSON.stringify(gltf)),length=Math.ceil(json.length/4)*4,out=new Uint8Array(28+length+bin.length+padded),v=new DataView(out.buffer);v.setUint32(0,0x46546c67,true);v.setUint32(4,2,true);v.setUint32(8,out.length,true);v.setUint32(12,length,true);v.setUint32(16,0x4e4f534a,true);out.fill(32,20,20+length);out.set(json,20);v.setUint32(20+length,bin.length+padded,true);v.setUint32(24+length,0x004e4942,true);out.set(bin,28+length);out.set(image,28+length+bin.length);return out;
}
